"use strict";(self.webpackChunkuniplus_developers=self.webpackChunkuniplus_developers||[]).push([["12708"],{27290(o){o.exports=JSON.parse('{"registro":{"codigo":"uniplus.selecao.aplicacao_de_modelo.derivado_sem_regra","status":422,"titulo":"O modelo cita derivado sem regra no processo nem no cat\xe1logo"},"descricao":{"codigo":"uniplus.selecao.aplicacao_de_modelo.derivado_sem_regra","requisitos":[],"oQueAconteceu":["Algumas perguntas e regras do modelo de formul\xe1rio usam um fato derivado: um\\nvalor que o sistema calcula a partir de outras respostas, por regras de\\nderiva\xe7\xe3o. Ao copiar o modelo, o processo traz para si as regras de deriva\xe7\xe3o\\nque o modelo cita, direta ou indiretamente: mant\xe9m as que o processo j\xe1 tem e\\ncopia as regras padr\xe3o do cat\xe1logo para as que n\xe3o tem.","Esta recusa sai para o fato derivado que o modelo cita quando o processo ainda\\nn\xe3o o deriva e o cat\xe1logo tamb\xe9m n\xe3o tem regra padr\xe3o para ele; nesse caso a\\nc\xf3pia n\xe3o sabe como calcul\xe1-lo. A recusa traz uma entrada por fato, na posi\xe7\xe3o\\n`derivacoes[<fato>]`, com o c\xf3digo do fato na mensagem. A modalidade de\\nconcorr\xeancia e a op\xe7\xe3o pelas cotas da lei n\xe3o entram aqui: elas v\xeam da\\ndistribui\xe7\xe3o de vagas do processo e t\xeam recusas pr\xf3prias\\n([`sem_distribuicao_de_vagas`](/erros/uniplus.selecao.aplicacao_de_modelo.sem_distribuicao_de_vagas),\\n[`sem_cota_da_lei_ofertada`](/erros/uniplus.selecao.aplicacao_de_modelo.sem_cota_da_lei_ofertada)).\\nNada foi alterado no processo."],"comoResolver":["Configure no processo as regras de deriva\xe7\xe3o do fato citado\\n(`PUT .../regras-derivacao`) e reaplique o modelo; o que o processo j\xe1 deriva \xe9\\nmantido como est\xe1. Se o processo n\xe3o deve derivar esse fato, escolha outro\\nmodelo que n\xe3o o cite."],"ondeAparece":["Aplica\xe7\xe3o de modelo de formul\xe1rio"]},"modulo":{"id":"selecao","nome":"Sele\xe7\xe3o","assunto":"Aplicacao de modelo"},"origem":{"repositorio":"unifesspa-edu-br/uniplus-api","commit":"fd5ea0ff72951399d2b2c1a4f29aeb3ea415db44"}}')}}]);